Object.assign(I18N.hi,{helpTitle:"मदद और वीडियो",watchVideo:"डेमो वीडियो देखें",replayTutorial:"ट्यूटोरियल फिर देखें",videoOffline:"वीडियो देखने के लिए इंटरनेट चाहिए।",tSkip:"छोड़ें",tNext:"आगे",tBack:"पीछे",tDone:"शुरू करें",tRemember:"मेरी पसंद सहेजें: ट्यूटोरियल दोबारा न दिखाएँ",tStep:"{total} में से {n}",
t1t:"Conti Chiari में आपका स्वागत है",t1b:"एक मिनट में दिखाता हूँ कि दोस्तों के साथ खर्च कैसे बाँटें। आप कभी भी छोड़ सकते हैं।",t2t:"आपके समूह",t2b:"समूह बदलने, नया बनाने या QR से जुड़ने के लिए ऊपर नाम पर टैप करें।",t3t:"लोग",t3b:"समूह टैब में शामिल लोगों को जोड़ें। यहीं समूह को ऑनलाइन करके QR से आमंत्रित भी कर सकते हैं।",t4t:"खर्च जोड़ें",t4b:"+ दबाएँ और लिखें क्या, कितना, किसने भुगतान किया और किनमें बाँटना है।",t5t:"किसे किसको देना है",t5b:"बैलेंस में कम से कम ट्रांसफ़र के साथ बकाया भुगतान दिखते हैं। कोई भुगतान करे तो “भुगतान हुआ” दबाएँ।",t6t:"लेन-देन में खोजें",t6b:"पुराने खर्च और भुगतान खोजें और हर व्यक्ति के आने-जाने वाले पैसे छाँटें।",t7t:"समूह चैट",t7b:"ऑनलाइन समूहों में आप दूसरों को लिख सकते हैं। संदेश एंड-टू-एंड एन्क्रिप्टेड हैं।",t8t:"सेटिंग्स",t8b:"प्रोफ़ाइल, भाषा, मुद्रा और बैकग्राउंड चुनें, और वीडियो व यह ट्यूटोरियल फिर देखें।",t9t:"सब तैयार!",t9b:"उदाहरण समूह आज़माएँ या अपना समूह बनाएँ।"});
